/**
 * Генератор переулочного города. Порядок шагов:
 *  1. План: магистрали, линии решётки, углы запретной зоны и промзоны, площадь, Управа.
 *  2. Решётка с дрожанием → лабиринт «растущее дерево» от магистралей + петли.
 *  3. Вырезание переулков (Z-изломы), магистралей, чистка «шипов».
 *  4. Зоны, штампы (площадь, Управа, кольцо запретной зоны), выходы из штампов.
 *  5. Дворы-колодцы, подъезды/арки, тупики, заводские дворы.
 *  6. Связность (flood fill по якорям 2×2 + тоннели), метрики, проверка.
 *  7. Канализация справа от города (sewers.ts), связанная с ним люками.
 * Результат детерминирован по seed.
 */
/** Печать причин неудачных попыток (для тестов): globalThis.__HL2D_DEBUG_GEN = true. */
const DEBUG_GEN = (globalThis as { __HL2D_DEBUG_GEN?: boolean }).__HL2D_DEBUG_GEN === true;

export function generateCity(seed: number): GameMap {
  return addSewers(addDam(addWastes(generateSurface(seed), seed), seed), seed);
}

/** Город без канализации (несколько попыток, лучшая по требованиям). */
function generateSurface(seed: number): GameMap {
  const attempts = GENERATOR.validation.attempts;
  const maxRun = GENERATOR.alley.maxStraight;
  let best: GameMap | null = null;
  let bestScore = Infinity;
  let lastError: unknown = null;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      const map = generateAttempt(seed, attempt);
      const problems = validateMap(map);
      const excess = Math.max(0, map.stats!.longestAlleyRun - maxRun);
      if (problems.length === 0 && excess === 0) return map;
      if (DEBUG_GEN) console.warn(`seed ${seed} попытка ${attempt}:`, [...problems, `прямая ${map.stats!.longestAlleyRun}`].join('; '));
      // Лучшая из неидеальных: сначала жёсткие требования, потом длина прямой.
      const score = problems.length * 1000 + excess;
      if (score < bestScore) {
        bestScore = score;
        best = map;
      }
    } catch (e) {
      lastError = e;
      if (DEBUG_GEN) console.warn(`seed ${seed} попытка ${attempt}:`, (e as Error).message);
    }
  }
  if (best) return best;
  throw lastError ?? new Error('Не удалось сгенерировать карту');
}

/** Список нарушений требований к карте (пустой — всё хорошо). */
export function validateMap(map: GameMap): string[] {
  const s = map.stats;
  const out: string[] = [];
  if (!s) return ['нет статистики'];
  if (s.components !== 1) out.push(`компонент связности: ${s.components}`);
  const [lo, hi] = GENERATOR.validation.buildingRatio;
  if (s.buildingRatio < lo || s.buildingRatio > hi) out.push(`доля зданий ${(s.buildingRatio * 100).toFixed(1)}%`);
  const need: [Poi['type'], number][] = [
    ['ration_window', 1], ['plaza_center', 1], ['nexus_gate', 1], ['nexus_desk', 1], ['cell', 7], ['common_cell', 1], ['bunk', 10], ['clerk_desk', 6], ['ota_spot', 6], ['restricted_gate', 1],
    ['checkpoint_post', 10], ['gate_post', 4], ['dorm', 2], ['villa', 2], ['outlands_exit', 2], ['shop_counter', 1],
    ['cwu_hq', 1], ['cwu_hire', 1], ['cwu_head_desk', 1], ['ration_line', 3], ['cwu_store', 1],
    ['arsenal', 1], ['arsenal_desk', 1], ['arsenal_window', 2], ['arsenal_ledger', 1], ['arsenal_drop', 8], ['arsenal_beacon', 1],
    ['arsenal_post', 4], ['arsenal_bench', 1], ['arsenal_pad', 1], ['arsenal_hall', 1], ['arsenal_issue', 4], ['arsenal_repair', 1],
    ['arsenal_breakroom', 1], ['arsenal_issue_room', 1], ['arsenal_ammo', 40], ['arsenal_grenades', 12], ['arsenal_rack', 20],
    ['prison', 1], ['prison_cell', 8], ['prison_post', 7], ['prison_desk', 1], ['prison_office', 1], ['prison_guardroom', 1], ['prison_evidence', 1], ['prison_yard', 1],
    ['prison_armory', 1], ['prison_rack', 6], ['prison_ammo', 4], ['prison_armory_door', 2], ['prison_interrogation', 1], ['prison_reception', 1], ['prison_sally', 1],
    ['prison_counter', 2], ['prison_intake', 1], ['prison_beacon', 2], ['prison_mast', 4], ['prison_drop', 4],
    ['academy', 1], ['academy_target', 3], ['academy_lane', 3], ['academy_desk', 8], ['academy_lectern', 1], ['academy_board', 3],
    ['academy_bunk', 7], ['academy_post', 2], ['academy_turnstile', 3], ['academy_head_desk', 1], ['academy_table', 2],
    ['academy_range', 1], ['academy_plac', 1], ['academy_class', 1], ['academy_barracks', 1], ['academy_mess', 1],
    ['academy_office', 1], ['academy_vakhta', 1], ['academy_lobby', 1],
    ['canteen', 1], ['canteen_table', 2], ['kiosk', 2], ['facade', 40], ['vendor_spot', 4],
  ];
  for (const [type, n] of need) if (map.poisOf(type).length < n) out.push(`нет точки ${type}`);
  if (!restrictedReachable(map)) out.push('ворота запретной зоны отрезаны');
  // Каждому пограничному КПП — передовой блиндаж повстанцев с ящиком и местами отдыха.
  for (const cp of map.poisOf('checkpoint_type')) {
    const inside = (p: Poi) => p.x >= cp.x && p.y >= cp.y && p.x < cp.x + (cp.w ?? 0) && p.y < cp.y + (cp.h ?? 0);
    if (!map.poisOf('dugout').some(inside)) out.push(`нет блиндажа у КПП (${cp.x},${cp.y})`);
    if (!map.poisOf('dugout_cache').some(inside)) out.push(`нет ящика в блиндаже КПП (${cp.x},${cp.y})`);
    if (map.poisOf('dugout_bunk').filter(inside).length < GENERATOR.validation.dugoutBunks) out.push(`мало мест отдыха в блиндаже КПП (${cp.x},${cp.y})`);
  }
  return out;
}

/**
 * Ворота запретной зоны ведут в город: у каждых рядом (в 3 тайлах) есть якорь главной компоненты
 * связности. Иначе зона отрезана (ворота упёрлись в застройку) — люки подполья в ней бесполезны.
 */
function restrictedReachable(map: GameMap): boolean {
  const gates = map.poisOf('restricted_gate');
  if (!gates.length) return false;
  const aw = map.width - 1;
  const ah = map.height - 1;
  const { labels, sizes } = labelComponents(buildAnchorWalk(map.tiles as Uint8Array, map.width, map.height), aw, ah);
  const main = sizes.indexOf(Math.max(...sizes));
  const r = 3;
  return gates.every((g) => {
    for (let y = Math.max(0, g.y - r); y <= Math.min(ah - 1, g.y + r); y++) {
      for (let x = Math.max(0, g.x - r); x <= Math.min(aw - 1, g.x + r); x++) {
        if (labels[y * aw + x] === main && map.zoneAtTile(x, y)?.kind !== 'restricted') return true;
      }
    }
    return false;
  });
}

/** Символы для зон без своего символа (кварталы — a…h, фиксированные зоны — заглавные). */
const ZONE_CHAR_POOL = '0123456789ijklmnopqrstuvwxyz!$%&*+-/;<=>?@^_~|';

const shrink = (r: Rect, d: number): Rect => ({ x: r.x + d, y: r.y + d, w: r.w - 2 * d, h: r.h - 2 * d });

export function generateAttempt(seed: number, attempt: number): GameMap {
  const t0 = performance.now();
  const G = GENERATOR;
  const W = WORLD.widthTiles;
  const H = WORLD.heightTiles;
  const rng = new Rng(hash2(seed, attempt, 0x5eed));
  const g = new GenGrid(W, H, G.border);
  const pois: Poi[] = [];

  // 1. План.
  const layout = planLayout(rng.fork(1), W, H, pickCheckpointTypes(seed));

  // 2. Решётка и лабиринт.
  const lat = Lattice.build(rng.fork(2), layout.xs, layout.ys);
  // Узлы линий проспектов — на асфальте (до конца проспекта: дальше на восток линия — обычная решётка).
  const hAvs: [number, Avenue][] = [[layout.hLine, layout.hAvenue], [layout.hLine2, layout.hAvenue2]];
  for (const n of lat.nodes) {
    for (const [line, av] of hAvs) {
      if (n.j !== line || n.x > av.band.x + av.band.w - 1) continue;
      n.y = avenueOffsetAt(av, n.x + 1) + 2;
      n.onAvenue = true;
    }
    if (layout.vAvenue && n.i === layout.vLine) {
      n.x = avenueOffsetAt(layout.vAvenue, n.y + 1) + 2;
      n.onAvenue = true;
    }
  }
  const restrictedInner = shrink(layout.restricted, G.restricted.wallThickness + 1);
  assignRegions(lat, {
    restricted: layout.restricted,
    restrictedInner,
    voids: [layout.nexus, ...(layout.cwuHq ? [layout.cwuHq.rect] : []), ...layout.checkpoints.map((c) => c.rect)],
    industrial: layout.industrial,
    // Граница Верхнего города: на её линии решётки узлов нет — переулки и улицы стену не пересекают.
    voidCols: [layout.upperLine],
  });
  // Улицы-артерии от проспекта и места под общежития и особняки (до лабиринта: он их обходит).
  // Проспект — вместе с рядами домов по сторонам.
  const R = facadeReach();
  const hb = layout.hAvenue.band;
  const hb2 = layout.hAvenue2.band;
  const streetBlocked = [layout.restricted, layout.industrial, layout.plaza, layout.nexus, ...(layout.cwuHq ? [layout.cwuHq.rect] : []), { x: hb.x, y: hb.y - R, w: hb.w, h: hb.h + 2 * R }, { x: hb2.x, y: hb2.y - R, w: hb2.w, h: hb2.h + 2 * R }, ...layout.checkpoints.map((c) => c.rect)];
  if (layout.vAvenue) {
    const vb = layout.vAvenue.band;
    streetBlocked.push({ x: vb.x - R, y: vb.y, w: vb.w + 2 * R, h: vb.h });
  }
  // Здания не встают на стену Верхнего города.
  streetBlocked.push({ x: layout.upperX - 2, y: 0, w: G.wealth.wall + 4, h: H });
  const streets = planStreets(lat, rng.fork(11), [layout.hLine, layout.hLine2], { rect: layout.plaza, side: layout.plazaSide }, streetBlocked, W, H, layout.nexus, layout.upperX);
  const starts: number[] = [];
  lat.nodes.forEach((n, k) => n.onAvenue && starts.push(k));
  for (const a of streets.arteries) for (const n of a.nodes) if (!starts.includes(n)) starts.push(n);
  const gate = layout.restrictedGates[0];
  if (gate) {
    const gx = gate.side === 'N' || gate.side === 'S' ? gate.pos : layout.restricted.x + layout.restricted.w / 2;
    const gy = gate.side === 'E' || gate.side === 'W' ? gate.pos : layout.restricted.y + layout.restricted.h / 2;
    let best = -1;
    let bestD = Infinity;
    lat.nodes.forEach((n, k) => {
      if (n.region !== 'restricted') return;
      const d = Math.hypot(n.x - gx, n.y - gy);
      if (d < bestD) {
        bestD = d;
        best = k;
      }
    });
    if (best >= 0) starts.push(best);
  }
  growMaze(lat, rng.fork(3), starts);
  addLoops(lat, rng.fork(4));
  // Переулки от проспекта пересекают ряд домов прямо — излом за ним.
  constrainAvenueLanes(lat, layout.hAvenue, layout.hLine);
  constrainAvenueLanes(lat, layout.hAvenue2, layout.hLine2);
  if (layout.vAvenue) constrainAvenueLanes(lat, layout.vAvenue, layout.vLine);
  finalizeEdges(lat, rng.fork(5));

  // 3. Вырезание.
  const carve = carveLattice(g, lat);
  const avenues = [layout.hAvenue, layout.hAvenue2, ...(layout.vAvenue ? [layout.vAvenue] : [])];
  for (const av of avenues) for (const r of avenueRects(av)) g.fillRect(r, T.STREET);
  const arteryRects = carveArteries(g, lat, streets);
  removeWallSpikes(g);
  // Стена Верхнего города с постами на проспектах.
  buildBorderWall(g, layout.upperX, [layout.hAvenue, layout.hAvenue2], pois);

  // 4. Зоны.
  const zones: Zone[] = [];
  // Символ зоны в JSON: заданный, а для многочисленных (улицы, общежития) — первый свободный из
  // ZONE_CHAR_POOL (без заглавных: ими помечены зоны пустоши и канализации, добавляемые позже).
  const addZone = (kind: ZoneKind, name: string, char: string | null): number => {
    if (char === null || zones.some((z) => z.char === char)) char = [...ZONE_CHAR_POOL].find((c) => !zones.some((z) => z.char === c)) ?? '?';
    zones.push({ id: zones.length, kind, name, char });
    return zones.length - 1;
  };
  // Названия кварталов — по полосе достатка.
  const nrng = rng.fork(7);
  const names = { slum: nrng.shuffle([...QUARTER_NAMES.slum]), old: nrng.shuffle([...QUARTER_NAMES.old]), upper: nrng.shuffle([...QUARTER_NAMES.upper]) };
  const used = { slum: 0, old: 0, upper: 0 };
  const quarterZones = layout.quarterSeeds.map((_, k) => {
    const d = layout.quarterDistricts[k];
    const list = names[d];
    return addZone('residential', list[used[d]++ % list.length], String.fromCharCode(97 + k));
  });
  const zHAv = addZone('avenue', ZONE_NAMES.avenue[0], 'A');
  const zVAv = layout.vAvenue ? addZone('avenue', ZONE_NAMES.avenue[1], 'B') : zHAv;
  const zHAv2 = addZone('avenue', ZONE_NAMES.avenue[2], null);
  const zPlaza = addZone('plaza', ZONE_NAMES.plaza, 'P');
  const zNexus = addZone('nexus', ZONE_NAMES.nexus, 'N');
  const zCells = addZone('cells', ZONE_NAMES.cells, 'K');
  const zInd = addZone('industrial', ZONE_NAMES.industrial, 'I');
  const zRes = addZone('restricted', ZONE_NAMES.restricted, 'R');
  // У каждого КПП — пять зон: внешний двор, шорт, лонг, внутренний двор (названия точек D — в имени), проходная.
  const zCheckpoints = layout.checkpoints.map((_, k) => {
    const base = ZONE_NAMES.checkpoints[k];
    const [pOut, pIn] = ZONE_NAMES.checkpointPoints[k];
    const chars = ZONE_NAMES.checkpointChars[k];
    return {
      outer: addZone('checkpoint', `${base} · ${pOut}`, chars[0]),
      short: addZone('checkpoint', `${base} · шорт`, chars[1]),
      long: addZone('checkpoint', `${base} · лонг`, chars[2]),
      inner: addZone('checkpoint', `${base} · ${pIn}`, chars[3]),
      gatehouse: addZone('checkpoint', `${base} · ${ZONE_NAMES.gatehouse}`, chars[4]),
    };
  });
  const zOut = addZone('outlands', ZONE_NAMES.outlands, 'O');
  const zShop = addZone('shop', ZONE_NAMES.shop, 'S');

  // Квартал тайла — ближайшее семя своей полосы достатка (квартал не перетекает через стену).
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const band = districtOfX(layout, x);
      let best = 0;
      let bestD = Infinity;
      layout.quarterSeeds.forEach((s, k) => {
        const d = (s.x - x) ** 2 + (s.y - y) ** 2 + (layout.quarterDistricts[k] === band ? 0 : 1e9);
        if (d < bestD) {
          bestD = d;
          best = k;
        }
      });
      g.zones[y * W + x] = quarterZones[best];
    }
  }
  // Полосы достатка — прямоугольники на всю высоту города.
  const DS = G.wealth;
  pois.push({ type: 'district', kind: 'slum', x: 0, y: 0, w: layout.oldX, h: H });
  pois.push({ type: 'district', kind: 'old', x: layout.oldX, y: 0, w: layout.upperX + DS.wall - layout.oldX, h: H });
  pois.push({ type: 'district', kind: 'upper', x: layout.upperX + DS.wall, y: 0, w: W - layout.upperX - DS.wall, h: H });
  g.setZoneRect(layout.industrial, zInd);
  g.setZoneRect(layout.restricted, zRes);
  const hRects = avenueRects(layout.hAvenue);
  const hRects2 = avenueRects(layout.hAvenue2);
  const inRects = (rs: Rect[], x: number, y: number) => rs.some((r) => x >= r.x && y >= r.y && x < r.x + r.w && y < r.y + r.h);
  for (let i = 0; i < W * H; i++) {
    if (g.tiles[i] !== T.STREET) continue;
    const x = i % W;
    const y = (i - x) / W;
    g.zones[i] = inRects(hRects, x, y) ? zHAv : inRects(hRects2, x, y) ? zHAv2 : zVAv;
  }
  // Улицы-артерии — свои зоны (вид avenue: асфальт, фонари, туда выходят жители).
  // Куда может выходить проезд к складу: проспект, площадь и улицы, что начинаются у проспекта.
  const roadTargets = new Set<number>([zHAv, zHAv2, zVAv]);
  arteryRects.forEach((rects, k) => {
    const z = addZone('avenue', ZONE_NAMES.streets[k % ZONE_NAMES.streets.length], null);
    if (streets.arteries[k]?.rooted) roadTargets.add(z);
    for (const r of rects) {
      for (let y = r.y; y < r.y + r.h; y++) for (let x = r.x; x < r.x + r.w; x++) if (g.get(x, y) === T.STREET && !inRects(hRects, x, y) && !inRects(hRects2, x, y)) g.zones[y * W + x] = z;
    }
  });

  // Штампы.
  stampPlaza(g, layout.plaza, layout.plazaSide, zPlaza, pois);

  const nexusRows = rotateTemplate(NEXUS_TEMPLATE, layout.nexusRot);
  const nexus = stampTemplate(g, nexusRows, layout.nexus.x, layout.nexus.y, (ch) => (ch === 'c' || ch === 'C' || ch === 'D' ? zCells : zNexus), pois);
  // Проспект изгибается — между фасадом Управы и асфальтом площадка, а не обрезки застройки.
  fillForecourt(g, layout.hAvenue, layout.nexus, zHAv);
  for (const exit of nexus.exits) {
    const isGate = exit.tiles.some((t) => g.get(t.x, t.y) === T.GATE);
    if (carveConnectorChecked(g, exit, G.connectorMax)) {
      if (isGate) {
        const mid = exit.tiles[Math.floor(exit.tiles.length / 2)];
        pois.push({ type: 'nexus_gate', x: mid.x, y: mid.y });
      }
    } else {
      for (const t of exit.tiles) g.set(t.x, t.y, T.METAL, true);
    }
  }
  for (const c of nexus.cells) pois.push({ type: 'cell', x: c.x + (c.w >> 1), y: c.y + (c.h >> 1) });
  for (const c of nexus.commonCells) pois.push({ type: 'common_cell', x: c.x + (c.w >> 1), y: c.y + (c.h >> 1), w: c.w, h: c.h });
  let yx0 = Infinity, yy0 = Infinity, yx1 = -Infinity, yy1 = -Infinity;
  for (let y = 0; y < nexusRows.length; y++) {
    for (let x = 0; x < nexusRows[0].length; x++) {
      if (nexusRows[y][x] !== ':') continue;
      yx0 = Math.min(yx0, x); yy0 = Math.min(yy0, y); yx1 = Math.max(yx1, x); yy1 = Math.max(yy1, y);
    }
  }
  pois.push({ type: 'nexus_yard', x: layout.nexus.x + ((yx0 + yx1) >> 1), y: layout.nexus.y + ((yy0 + yy1) >> 1) });

  // Общежития и особняки лоялистов — вдоль артерий, входом на улицу.
  const stampBuilding = (rows: string[], rect: Rect, zone: number, kind: 'dorm' | 'villa', id: number) => {
    const res = stampTemplate(g, rows, rect.x, rect.y, () => zone, pois);
    for (const exit of res.exits) if (!carveConnectorChecked(g, exit, G.connectorMax)) carveConnector(g, exit, G.connectorMax);
    for (const r of res.rooms) pois.push({ type: 'home', x: r.x, y: r.y, w: r.w, h: r.h, kind, id });
    for (const r of res.commons) pois.push({ type: kind === 'dorm' ? 'dorm_common' : 'villa_living', x: r.x, y: r.y, w: r.w, h: r.h, kind, id });
    pois.push({ type: kind, x: rect.x, y: rect.y, w: rect.w, h: rect.h, id });
  };
  streets.dorms.forEach((p, k) => {
    const z = addZone('residential', `${ZONE_NAMES.dorm} №${k + 1}`, null);
    stampBuilding(faceTemplate(DORM_TEMPLATE, p.face), p.rect, z, 'dorm', k);
  });
  if (streets.villas.length) {
    const z = addZone('residential', ZONE_NAMES.villas, null);
    streets.villas.forEach((p, k) => stampBuilding(faceTemplate(VILLA_TEMPLATE, p.face), p.rect, z, 'villa', k));
  }

  // Штаб ТС на главном проспекте: цех фасовки, отдых, столовая, кабинет главы, приёмная найма.
  if (layout.cwuHq) {
    const p = layout.cwuHq;
    const z = addZone('cwu_hq', ZONE_NAMES.cwuHq, null);
    const res = stampTemplate(g, faceTemplate(CWU_HQ_TEMPLATE, p.face), p.rect.x, p.rect.y, () => z, pois);
    // Фасад — прямо на асфальт (проспект изгибается — площадка до края).
    fillForecourt(g, layout.hAvenue, p.rect, zHAv);
    for (const exit of res.exits) if (!carveConnectorChecked(g, exit, G.connectorMax)) carveConnector(g, exit, G.connectorMax);
    const area = (mark: string, type: Poi['type']) => {
      for (const r of res.areas[mark] ?? []) pois.push({ type, x: r.x, y: r.y, w: r.w, h: r.h });
    };
    area('l', 'cwu_lounge');
    area('n', 'cwu_canteen');
    area('e', 'cwu_office');
    area('a', 'cwu_lobby');
    area('p', 'cwu_production');
    pois.push({ type: 'cwu_hq', x: p.rect.x, y: p.rect.y, w: p.rect.w, h: p.rect.h });
  }

  // Склад Протектората на окраине: зал хранения, площадка корабля, кабинет кладовщика, караулка, мастерская.
  if (streets.arsenal) {
    const p = streets.arsenal;
    const z = addZone('arsenal', ZONE_NAMES.arsenal, null);
    const res = stampTemplate(g, faceTemplate(ARSENAL_TEMPLATE, p.face), p.rect.x, p.rect.y, () => z, pois);
    // Подъезд — улицей: площадка перед фасадом и проезд до ближайшей улицы (не переулок).
    const A = G.arsenal;
    const road = addZone('avenue', ZONE_NAMES.arsenalRoad, null);
    roadTargets.add(zPlaza);
    if (!carveAccessRoad(g, p.rect, p.face, A.road.width, A.road.apron, A.road.maxLen, road, (i) => roadTargets.has(g.zones[i]))) {
      for (const exit of res.exits) if (!carveConnectorChecked(g, exit, G.connectorMax)) carveConnector(g, exit, G.connectorMax);
    }
    const area = (mark: string, type: Poi['type']) => {
      for (const r of res.areas[mark] ?? []) pois.push({ type, x: r.x, y: r.y, w: r.w, h: r.h });
    };
    area('s', 'arsenal_hall');
    area('Y', 'arsenal_pad');
    area('f', 'arsenal_issue_room');
    area('e', 'arsenal_office');
    area('1', 'arsenal_breakroom');
    area('j', 'arsenal_vault_room');
    area('z', 'arsenal_guardroom');
    area('N', 'arsenal_workshop');
    pois.push({ type: 'arsenal', x: p.rect.x, y: p.rect.y, w: p.rect.w, h: p.rect.h });
  }

  // Тюрьма Протектората: блок камер, шлюз с оружейной и допросной, караулка, кабинет, приёмная, изъятое,
  // двор-площадка с маяками; подъезд — улицей.
  if (streets.prison) {
    const p = streets.prison;
    const z = addZone('prison', ZONE_NAMES.prison, null);
    const res = stampTemplate(g, faceTemplate(PRISON_TEMPLATE, p.face), p.rect.x, p.rect.y, () => z, pois);
    const A = G.prison;
    const road = addZone('avenue', ZONE_NAMES.prisonRoad, null);
    roadTargets.add(zPlaza);
    if (!carveAccessRoad(g, p.rect, p.face, A.road.width, A.road.apron, A.road.maxLen, road, (i) => roadTargets.has(g.zones[i]))) {
      for (const exit of res.exits) if (!carveConnectorChecked(g, exit, G.connectorMax)) carveConnector(g, exit, G.connectorMax);
    }
    for (const r of res.areas['6'] ?? []) pois.push({ type: 'prison_cell', x: r.x + (r.w >> 1), y: r.y + (r.h >> 1), w: r.w, h: r.h });
    const area = (mark: string, type: Poi['type']) => {
      for (const r of res.areas[mark] ?? []) pois.push({ type, x: r.x, y: r.y, w: r.w, h: r.h });
    };
    area('0', 'prison_guardroom');
    area('9', 'prison_office');
    area('&', 'prison_evidence');
    area('8', 'prison_yard');
    area('(', 'prison_armory');
    area('$', 'prison_interrogation');
    area('@', 'prison_reception');
    area('<', 'prison_sally');
    pois.push({ type: 'prison', x: p.rect.x, y: p.rect.y, w: p.rect.w, h: p.rect.h });
  }

  // Академия ВС: вахта с турникетом, плац, тир, класс, кубрик, столовая, кабинет; подъезд — улицей.
  if (streets.academy) {
    const p = streets.academy;
    const z = addZone('academy', ZONE_NAMES.academy, null);
    const res = stampTemplate(g, faceTemplate(ACADEMY_TEMPLATE, p.face), p.rect.x, p.rect.y, () => z, pois);
    const A = G.academy;
    const road = addZone('avenue', ZONE_NAMES.academyRoad, null);
    roadTargets.add(zPlaza);
    if (!carveAccessRoad(g, p.rect, p.face, A.road.width, A.road.apron, A.road.maxLen, road, (i) => roadTargets.has(g.zones[i]))) {
      for (const exit of res.exits) if (!carveConnectorChecked(g, exit, G.connectorMax)) carveConnector(g, exit, G.connectorMax);
    }
    const area = (mark: string, type: Poi['type']) => {
      for (const r of res.areas[mark] ?? []) pois.push({ type, x: r.x, y: r.y, w: r.w, h: r.h });
    };
    area('и', 'academy_range');
    area('э', 'academy_office');
    area('л', 'academy_class');
    area('п', 'academy_plac');
    area('г', 'academy_barracks');
    area('ы', 'academy_mess');
    area('В', 'academy_vakhta');
    area('в', 'academy_lobby');
    pois.push({ type: 'academy', x: p.rect.x, y: p.rect.y, w: p.rect.w, h: p.rect.h, face: p.face });
  }

  stampRestricted(g, layout.restricted, layout.restrictedGates, rng.fork(8), pois);

  // Пограничные КПП. Выход только один — в сторону города (к проспекту). Тип КПП — свой шаблон и своя карта
  // частей (checkpoints.ts); POI checkpoint_type запоминает тип для боевого ИИ и интерфейса.
  layout.checkpoints.forEach((cp, k) => {
    const def = CHECKPOINTS[cp.type];
    const { rows, sections } = checkpointRows(def, cp.mirror);
    const zoneKey = { o: 'outer', s: 'short', l: 'long', i: 'inner', g: 'gatehouse' } as const;
    // Пустошь перед КПП (и завалы на ней) — зона пустоши, остальное — части КПП.
    const zoneOf = (_ch: string, x: number, y: number) => {
      const part = sections[y][x] as SectionChar;
      return part === '-' ? zOut : zCheckpoints[k][zoneKey[part]];
    };
    const res = stampTemplate(g, rows, cp.rect.x, cp.rect.y, zoneOf, pois);
    const cityDx = cp.mirror ? -1 : 1;
    for (const exit of res.exits) {
      if (exit.dx !== cityDx) continue;
      if (!carveConnectorChecked(g, exit, G.connectorMax)) carveConnector(g, exit, G.connectorMax);
    }
    let sx = 0, sy = 0, n = 0;
    for (let y = 0; y < rows.length; y++) for (let x = 0; x < rows[0].length; x++) if (isOutlandsGround(rows[y][x])) { sx += x; sy += y; n++; }
    pois.push({ type: 'outlands_exit', x: cp.rect.x + Math.round(sx / n), y: cp.rect.y + Math.round(sy / n) });
    // Передовой блиндаж повстанцев в полосе пустоши: внутренний пол и сторона входа (ящик и койки — POI из стампа).
    for (const d of dugoutsOf(rows)) pois.push({ type: 'dugout', x: cp.rect.x + d.x, y: cp.rect.y + d.y, w: d.w, h: d.h, face: d.face });
    pois.push({ type: 'checkpoint_type', x: cp.rect.x, y: cp.rect.y, w: cp.rect.w, h: cp.rect.h, kind: cp.type, face: cp.mirror ? 'E' : 'W' });
  });

  // Улицы старого города: ряды домов вдоль проспектов, площади и артерий; на главном проспекте и
  // площади — лавки, кафе и общая столовая; посередине проспекта — ларьки и клумбы.
  const pc = pois.find((p) => p.type === 'plaza_center')!;
  const frontages = [
    ...avenueFrontages(layout.hAvenue, true),
    ...avenueFrontages(layout.hAvenue2, false),
    ...rectFrontages(layout.plaza, 'plaza', true, layout.plazaSide === 'N' ? 'S' : 'N'),
    ...(layout.vAvenue ? avenueFrontages(layout.vAvenue, false) : []),
    ...arteryRects.flatMap((rects, k) => arteryFrontages(rects, streets.arteries[k].width)),
  ];
  buildFacades(g, rng.fork(12), {
    frontages,
    plazaCenter: pc,
    addZone: (kind, name) => (kind === 'shop' && name === ZONE_NAMES.shop ? zShop : addZone(kind, name, null)),
    pois,
  });
  const decor = rng.fork(13);
  // От проходных западных КПП до восточного конца проспектов.
  const cpEdge = Math.max(...layout.checkpoints.map((c) => c.rect.x + c.rect.w));
  let kiosks = placeAvenueDecor(g, decor, layout.hAvenue, pois, 0, cpEdge);
  kiosks += placeAvenueDecor(g, decor, layout.hAvenue2, pois, kiosks, cpEdge);
  if (layout.vAvenue) placeAvenueDecor(g, decor, layout.vAvenue, pois, kiosks);
  // Магазин ТС не встал в ряд домов — комната в застройке неподалёку от площади.
  if (!pois.some((p) => p.type === 'shop_counter')) stampShop(g, rng.fork(9), pc.x, pc.y, zShop, pois);

  // 5. Детали застройки.
  const zoneKindAt = (x: number, y: number) => zones[g.zones[y * W + x]]?.kind;
  const feat = addFeatures(g, rng.fork(6), {
    isResidential: (x, y) => zoneKindAt(x, y) === 'residential',
    isIndustrial: (x, y) => g.zones[y * W + x] === zInd,
    pois,
  });

  // 5б. Городок: часть участков застройки у переулков — жилые дома с комнатой и дверью.
  addHomes(g, rng.fork(10), seed + attempt, (x, y) => zoneKindAt(x, y) === 'residential', pois);

  // 6. Связность.
  const center = pois.find((p) => p.type === 'plaza_center')!;
  const conn = ensureConnectivity(g, center.x, center.y, G.connectivity);

  const stats: MapStats = {
    seed,
    attempt,
    genMs: Math.round(performance.now() - t0),
    widthTiles: W,
    heightTiles: H,
    buildingRatio: buildingRatio(g.tiles),
    walkableTiles: g.countPassable(),
    longestAlleyRun: longestAlleyRun(g.tiles, W, H),
    avenues: avenues.length,
    deadEnds: carve.deadEnds + feat.stubs,
    chokepoints: carve.narrow,
    courtyards: feat.courtyards,
    passages: feat.passages,
    arches: feat.arches,
    stubs: feat.stubs,
    industrialYards: feat.yards,
    initialComponents: conn.initialComponents,
    tunnels: conn.tunnels,
    fragmentsFilled: conn.fragmentsFilled,
    unreachableRemoved: conn.unreachableRemoved,
    components: conn.finalComponents,
  };

  return new GameMap(W, H, WORLD.tileSize, g.tiles, g.zones, zones, pois, seed, `Верхнеречье · seed ${seed}`, stats);
}
